MultiLanguageSpellData['ru'][79966] = {name = "Освящение", additional_info = "22% от базовой мана\nМгновенное действие\n[q]Освящает участок земли, на котором стоит заклинатель, нанося урон от светлой магии в течение 8 сек. всем противникам, ступившим на освященную землю."}
MultiLanguageSpellData['ru'][79967] = {name = "Щит небес", additional_info = "10% от базовой мана\nМгновенное действие\n[q]Повышает вероятность блокировать удар на 30% на 10 сек. Если атака блокирована, атакующему наносится урон от светлой магии. При каждом блоке расходуется 1 заряд. 3 заряда:зарядов."}
MultiLanguageSpellData['ru'][79968] = {name = "Благословение королей", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Благословляет дружественную цель, на 5 мин. повышая ее силу, ловкость, выносливость и интеллект на 5%."}
MultiLanguageSpellData['ru'][79970] = {name = "Божественная буря", additional_info = "{20% от базовой мана} {Дистанция ближнего боя}\nМгновенное действие\n[q]Мгновенная атака оружием, наносящая урон от светлой магии 4 противникам:противникам в радиусе 8 м."}
