MultiLanguageSpellData['ru'][80015] = {name = "Верный выстрел", additional_info = "Радиус действия: 35 м\nПрименение: 1.5 сек\nТребуется: Оружие дальнего боя\n[q]Верный выстрел, наносящий противнику увеличенный на (Ranged attack power * 0.1 + 0) ед. урон от оружия."}
