MultiLanguageSpellData['ru'][82200] = {name = "Шприц с лечебным зельем", additional_info = "Применение: 5 сек\nТребуется: Перчатки\nИнструменты: Тангенциальный вращатель\nИнгредиенты:\nГорсть обсидиановых болтов , Искрящийся эфир\n[q]Оснащает перчатки шприцом, позволяющим впрыскивать легендарное лечебное зелье прямо в вену для усиленного эффекта. Для использования требуется высокий навык инженерного дела.\n\n Можно применить только к своим перчаткам, после усовершенствования они становятся персональным предметом."}
MultiLanguageSpellData['ru'][82201] = {name = "Мана-ингалятор Z50", additional_info = "Применение: 5 сек\nТребуется: Перчатки\nИнструменты: Тангенциальный вращатель\nИнгредиенты:\nГорсть обсидиановых болтов , Искрящийся эфир\n[q]Прикрепляет к перчаткам ингалятор, позволяющий вдыхать легендарное зелье маны, что усиливает действие зелья. Для использования требуется высокий навык инженерного дела.\n\n Можно применить только к своим перчаткам, после усовершенствования они становятся персональным предметом."}
