MultiLanguageSpellData['ru'][90411] = {name = "[q0]Потрясающий дверной молоток", additional_info = "Применение: 3 сек 5\n[q]Можно только гадать, чью дверь в свое время украшал этот артефакт. Этот, ммм... дверной молоток выполнен в форме пышной дворфийской женщины, держащей в руках несколько пинт пива. Особенно хороша лучезарная редкозубая улыбка приветливой хозяюшки.\n[q0]Потрясающий дверной молоток\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][90412] = {name = "[q0]Украшенный резьбой каблук", additional_info = "Применение: 3 сек 5\n[q]Исключительное внимание, которое сапожник уделил каждой детали этого каблука, подсказывает вам, что сапог обладал магическими свойствами. Рисунок довольно абстрактен, но среди завитков орнамента и стилизованных изображений узлов можно различить крошечные силуэты лесных зверей – белок, оленей и, кажется, скунса.\n[q0]Украшенный резьбой каблук\nСтановится персональным при поднятии"}
MultiLanguageSpellData['ru'][90413] = {name = "[q0]Золотая ночная ваза", additional_info = "Применение: 3 сек 5\n[q]Каждая мелочь в жизни богатых и знаменитых должна отражать изысканный вкус хозяина и величие его предков. К примеру, эта ночная ваза украшена орнаментом из речных волн и резвящихся рыбок, что свидетельствует...\n[q0]Золотая ночная ваза\nСтановится персональным при поднятии"}
