MultiLanguageSpellData['ru'][90506] = {name = "[q0]Обугленный посох жреца тени Анунда", additional_info = "Применение: 3 сек 5\n[q]Деревянный посох дочерна обожжен огнем тайной магии. Та же судьба, видимо, постигла и его хозяина.\n[q0]Обугленный посох жреца тени Анунда\nСтановится персональным при поднятии"}
