MultiLanguageSpellData['ru'][90853] = {name = "[q0]Ножной браслет с золотыми колокольчиками", additional_info = "Применение: 3 сек 5\n[q]К тонкому обручу из фиолетового металла прикреплено 17 крохотных колокольчиков и несколько крупных бусин из желтого дутого стекла. Скорее всего, браслет носила танцовщица или юная светская красавица.\n[q0]Ножной браслет с золотыми колокольчиками\nСтановится персональным при поднятии"}
