MultiLanguageSpellData['ru'][348700] = {name = "Печать крови", additional_info = "Мана: 210\nМгновенное действие\n[q]Все атаки ближнего боя наносят дополнительно 40% обычного урона от оружия в виде урона от светлой магии, но паладин теряет здоровье в объеме 10% от общего нанесенного урона.\n\n Высвобождение энергии печати наносит противнику 40 ед. урона от светлой магии и лишает паладина здоровья в объеме 33% от нанесенного урона."}
